9: import { readFileSync, readdirSync, statSync } from 'node:fs';
10: import { join, relative, sep } from 'node:path';
11: import { parse } from 'yaml';
12: 
13: const SKIP_DIRS = new Set([
14:   '.git',
15:   'node_modules',
16:   'coverage',
17:   'test-results',
18:   'playwright-report',
19:   '.cache',
20: ]);
21: 
22: const errors = [];
23: const fail = (msg) => errors.push(msg);
24: 
25: function walk(dir, out = []) {
26:   for (const name of readdirSync(dir)) {
27:     if (SKIP_DIRS.has(name)) continue;
28:     const full = join(dir, name);
29:     if (statSync(full).isDirectory()) walk(full, out);
30:     else out.push(relative('.', full).split(sep).join('/'));
31:   }
32:   return out;
33: }
34: 
35: function globToRegExp(glob) {
36:   const escaped = glob.replace(/[.+^${}()|[\]\\]/g, '\\$&');
37:   const body = escaped.replace(/\*\*/g, ' ').replace(/\*/g, '[^/]*').replace(/ /g, '.*');
38:   return new RegExp(`^${body}$`);
39: }
