41: const repoFiles = walk('.');
42: const slices = parse(readFileSync('slices.yaml', 'utf8'))?.slices ?? [];
43: const storymap = parse(readFileSync('storymap.yaml', 'utf8'));
44: 
45: const unitRolePatterns = slices.flatMap((s) => s?.roles?.unit_tests ?? []);
46: const e2eRolePatterns = slices.flatMap((s) => s?.roles?.e2e_specs ?? []);
47: 
48: const refs = [];
49: for (const slice of slices) {
50:   for (const t of slice?.tests ?? [])
51:     refs.push({ where: `slices.yaml slice \`${slice.id}\``, ...refOf(t) });
52: }
53: for (const activity of storymap?.activities ?? []) {
54:   for (const task of activity?.tasks ?? []) {
55:     for (const story of task?.stories ?? []) {
56:       for (const t of story?.tests ?? [])
57:         refs.push({ where: `storymap task \`${task.id}\``, ...refOf(t) });
58:     }
59:   }
60: }
61: 
62: function refOf(t) {
63:   const key = t && typeof t === 'object' ? Object.keys(t)[0] : undefined;
64:   return { kind: key, value: key ? String(t[key]) : '' };
65: }
66: 
67: function underRole(value, patterns) {
68:   return patterns.some((p) => globToRegExp(p).test(value));
69: }
70: 
71: if (refs.length === 0) {
72:   fail('no test refs found in either manifest — empty selection tests nothing (non-vacuity).');
73: }
74: 
75: let checkedUnit = 0;
76: let checkedE2e = 0;
77: 
78: for (const { where, kind, value } of refs) {
79:   if (!['unit', 'e2e'].includes(kind)) {
80:     fail(`${where}: ref \`${JSON.stringify(value)}\` is not unit:/e2e:.`);
81:     continue;
82:   }
83:   const [target, ...fragmentParts] = value.split('::');
84:   const fragment = fragmentParts.join('::');
85:   if (!target || !fragment) {
86:     fail(`${where}: ref \`${value}\` must be \`<target>::<title fragment>\`.`);
87:     continue;
88:   }
89: 
90:   if (kind === 'unit') {
91:     checkedUnit++;
92:     if (!repoFiles.includes(target)) {
93:       fail(`${where}: unit file \`${target}\` does not exist.`);
94:       continue;
95:     }
96:     if (!underRole(target, unitRolePatterns)) {
97:       fail(`${where}: unit file \`${target}\` is not under any slice's unit_tests role.`);
98:     }
99:     if (!readFileSync(target, 'utf8').includes(fragment)) {
100:       fail(`${where}: fragment \`${fragment}\` not found in \`${target}\`.`);
101:     }
102:   } else {
103:     checkedE2e++;
104:     const candidates = repoFiles.filter(
105:       (f) =>
106:         f.endsWith(`/${target}.spec.js`) ||
107:         f === `e2e/${target}.spec.js` ||
108:         f === `${target}.spec.js`,
109:     );
110:     if (candidates.length === 0) {
111:       fail(`${where}: no spec file \`${target}.spec.js\` found under e2e/.`);
112:       continue;
113:     }
114:     const spec = candidates[0];
115:     if (!underRole(spec, e2eRolePatterns)) {
116:       fail(`${where}: spec \`${spec}\` is not under any slice's e2e_specs role.`);
117:     }
118:     if (!readFileSync(spec, 'utf8').includes(fragment)) {
119:       fail(`${where}: fragment \`${fragment}\` not found in \`${spec}\`.`);
120:     }
121:   }
122: }
123: 
124: if (errors.length > 0) {
125:   for (const e of errors) console.error(`guard-story-refs: ${e}`);
126:   process.exit(1);
127: }
128: console.log(
129:   `guard-story-refs: OK (${refs.length} refs — ${checkedUnit} unit, ${checkedE2e} e2e — all files and fragments resolve)`,
