// DOCUMENTS: the Stage 6 component — a DNS resolver with a tick-TTL ledger
// that mirrors the Cache's ledger pattern (js/sim/cache.js). The
// authoritative table lives in-component (example.com -> 10.1; Stage 6b adds
// a CDN name); lookup() consults it only on a cache miss or an expired
// entry, and a hit inside ttlTicks increments cachedHits with NO
// authoritative consult. Determinism: no clock, no RNG — time arrives as
// the `currentTick` argument, the same way the Cache keeps time.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer (fail-loud over
// silent mis-configuration), while an unknown name answers { status: 'NX' }
// and never throws at the DNS layer (the fail-loud throw rule belongs to
// cross-subnet addresses in network.js).
const MINI_IP = /^\d+\.\d+$/;

export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!MINI_IP.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  const authoritative = new Map([['example.com', '10.1']]);
  const entries = new Map(); // name -> { name, target, cachedAtTick, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let authoritativeHits = 0;
  let evictions = 0;
  let lastLookup = null;

  // An entry is stale the moment the current tick reaches its expiry —
  // the same tick math as the Cache (cached at T, alive through T + ttl - 1).
  function evictExpired(currentTick = 0) {
    for (const entry of entries.values()) {
      if (currentTick >= entry.expiresAtTick) {
        entries.delete(entry.name);
        evictions += 1;
      }
    }
  }

  function lookup(name, currentTick = 0) {
    lookups += 1;
    evictExpired(currentTick);
    const entry = entries.get(name);
    if (entry) {
      // Ledger hit: the authoritative table is not touched at all.
      cachedHits += 1;
      lastLookup = { name, status: 'OK', source: 'cache', atTick: currentTick };
      return { status: 'OK', name, target: entry.target, source: 'cache', atTick: currentTick };
    }
    // Miss or expired entry: the only path that consults the table.
    const target = authoritative.get(name) ?? null;
    if (target === null) {
      lastLookup = { name, status: 'NX', atTick: currentTick };
      return { status: 'NX', name, atTick: currentTick };
    }
    authoritativeHits += 1;
    entries.set(name, {
      name,
      target,
      cachedAtTick: currentTick,
      expiresAtTick: currentTick + ttlTicks,
    });
    lastLookup = { name, status: 'OK', source: 'authoritative', atTick: currentTick };
    return { status: 'OK', name, target, source: 'authoritative', atTick: currentTick };
  }

  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      authoritativeHits,
      evictions,
      lastLookup,
      authoritative: Object.fromEntries(authoritative),
      cache: [...entries.values()].map((e) => ({
        name: e.name,
        target: e.target,
        cachedAtTick: e.cachedAtTick,
        expiresAtTick: e.expiresAtTick,
        ttlRemaining: e.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    evictExpired,
    lookup,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 component — a Router that joins the 10.x and 20.x
// network instances. Any cross-subnet frame takes exactly one router hop
// (routed += 1); frames addressed to the router's own interfaces are the
// frames it terminates itself, so the 20-side (20.1) is the only reachable
// target in subnet 20 in Stage 6a — Stage 6b occupies it with the CDN edge.
// Same-subnet sends stay entirely inside their Network and do not see the
// Router at all.
//
// CHECKS: both interface addresses are validated as two-number mini-IPs and
// must sit in different subnets — a router with both legs in one subnet is a
// mis-configuration that fails loud.
export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  for (const addr of [leftAddress, rightAddress]) {
    if (!/^\d+\.\d+$/.test(addr)) {
      throw new Error(`router: invalid mini-IP address ${addr}`);
    }
  }
  if (leftAddress.split('.')[0] === rightAddress.split('.')[0]) {
    throw new Error(
      `router: both legs sit in subnet ${leftAddress.split('.')[0]}.x (${leftAddress}, ${rightAddress})`,
    );
  }
  let routed = 0;
  const received = []; // frames terminated at the router's own interface

  return {
    get leftAddress() {
      return leftAddress;
    },
    get rightAddress() {
      return rightAddress;
    },

    // One cross-subnet hop: the Network hands frames here before the peer
    // network resolves them, so 20.9's fail-loud throw still happens on the
    // far side — after the hop was counted.
    hop() {
      routed += 1;
    },

    // Frames the router terminates at its own interface. The slim protocol
    // answer names both legs; it is the only body 20.1 serves in 6a.
    handleRequest() {
      return `200 Router ${leftAddress} ⇄ ${rightAddress}`;
    },

    // deliverToQueue's cross-subnet record, isYou riding through untouched.
    enqueue(record) {
      received.push(record);
      return record;
    },

    lastReceived() {
      return received[received.length - 1] ?? null;
    },

    snapshot() {
      return {
        leftAddress,
        rightAddress,
        routed,
        received: [...received],
      };
    },
  };
}

// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages. Today it carries slim HTTP
// requests to a registered server; later stages attach more components
// without changing the send/enqueue contract. Stage 6 adds optional
// cross-subnet routing: a Network built with a `subnet` can hand frames for
// another subnet to its attached Router, which hops them into the peer
// network — exactly one router hop per cross-subnet frame. Same-subnet
// sends keep the send/deliverToQueue contract from Stages 1-5 unchanged.
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>); a subnet-scoped Network rejects foreign-subnet
// registrations and senders; sends to unregistered hosts fail loud — an
// unknown same-subnet host on this Network, or (after the one router hop)
// an unknown host on the peer Network, such as 20.9 in Stage 6a.
const MINI_IP = /^\d+\.\d+$/;

export function createNetwork({ subnet = null } = {}) {
  const servers = new Map();
  // Gateway to another subnet: { router, remoteAddress, peer }, set by
  // setGateway once both networks and the Router exist.
  let gateway = null;

  const netOf = (addr) => addr.split('.')[0];

  function validateFormat(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function validateLocal(addr) {
    validateFormat(addr);
    if (subnet !== null && netOf(addr) !== subnet) {
      throw new Error(`network: address ${addr} is outside subnet ${subnet}.x`);
    }
  }

  function resolve(address) {
    validateLocal(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  // Shared body of send/deliverToQueue: the local path first, then the one
  // router hop into the peer network, which resolves fail-loud on its own
  // side (20.9). `deliver` receives the resolved local server.
  function dispatch({ from, to, deliver }) {
    validateLocal(from);
    if (servers.has(to)) {
      deliver(resolve(to));
      return null;
    }
    validateFormat(to);
    if (gateway && netOf(to) === netOf(gateway.remoteAddress)) {
      gateway.router.hop();
      gateway.peer.receiveRouted({ from, to });
      return gateway;
    }
    throw new Error(`network: no server at ${to}`);
  }

  return {
    registerServer(address, server) {
      validateLocal(address);
      servers.set(address, server);
    },

    resolve,

    setGateway(next) {
      gateway = next;
    },

    // The far side of a routed frame: no subnet check on `from` (the frame
    // originates in the peer subnet), then the normal fail-loud resolve.
    receiveRouted({ from, to }) {
      validateFormat(from);
      const server = resolve(to);
      return { from, to, server };
    },

    send({ from, to, request }) {
      let response = null;
      dispatch({
        from,
        to,
        deliver: (server) => {
          response = server.handleRequest(request);
        },
      });
      if (response !== null) return { from, to, request, response };
      return { from, to, request, response: gateway };
    },

