// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages. Today it carries slim HTTP
// requests to a registered server; later stages attach more components
// without changing the send/enqueue contract. Stage 6 adds optional
// cross-subnet routing: a Network built with a `subnet` hands frames for
// another subnet to its attached Router, which hops them into the peer
// network — exactly one router hop per cross-subnet frame. Same-subnet
// sends keep the send/deliverToQueue contract from Stages 1-5 unchanged.
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>); a subnet-scoped Network rejects foreign-subnet
// registrations and senders; sends to unregistered hosts fail loud — an
// unknown same-subnet host on this Network, or (after the one router hop)
// an unknown host on the peer Network, such as 20.9 in Stage 6a.
const MINI_IP = /^\d+\.\d+$/;

export function createNetwork({ subnet = null } = {}) {
  const servers = new Map();
  // Gateway to another subnet: { router, remoteAddress, peer }, set by
  // setGateway once both networks and the Router exist.
  let gateway = null;

  const netOf = (addr) => addr.split('.')[0];

  function validateFormat(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function validateLocal(addr) {
    validateFormat(addr);
    if (subnet !== null && netOf(addr) !== subnet) {
      throw new Error(`network: address ${addr} is outside subnet ${subnet}.x`);
    }
  }

  function resolve(address) {
    validateLocal(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  // Shared body of send/deliverToQueue: the local path first, then the one
  // router hop into the peer network, whose receiveRouted resolves
  // fail-loud on its own side (20.9). Returns 'local', 'routed', or throws.
  function dispatch({ from, to, deliverLocal, deliverRouted }) {
    validateLocal(from);
    if (servers.has(to)) {
      deliverLocal(resolve(to));
      return 'local';
    }
    validateFormat(to);
    if (gateway && netOf(to) === netOf(gateway.remoteAddress)) {
      gateway.router.hop();
      const { server } = gateway.peer.receiveRouted({ from, to });
      deliverRouted(server);
      return 'routed';
    }
    throw new Error(`network: no server at ${to}`);
  }

  return {
    registerServer(address, server) {
      validateLocal(address);
      servers.set(address, server);
    },

    resolve,

    setGateway(next) {
      gateway = next;
    },

    // The far side of a routed frame: no subnet check on `from` (the frame
    // originates in the peer subnet), then the normal fail-loud resolve.
    receiveRouted({ from, to }) {
      validateFormat(from);
      return { from, to, server: resolve(to) };
    },

    send({ from, to, request }) {
      let response = null;
      const path = dispatch({
        from,
        to,
        deliverLocal: (server) => {
          response = server.handleRequest(request);
        },
        deliverRouted: (server) => {
          response = server.handleRequest(request);
        },
      });
      // The routed record keeps the caller's own from/to — the Router's hop
      // is counted inside router.hop(), not rewritten onto the frame.
      return { from, to, request, response, routed: path === 'routed' ? gateway.router : null };
    },

    // `isYou` rides through untouched: the engine marks the learner's own
    // interactive-browser request, the server stores it on the queue row —
    // and the Router's own receive path passes the whole record through.
    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      const record = { id, from, to, request, atTick, isYou };
      dispatch({
        from,
        to,
        deliverLocal: (server) => server.enqueue(record),
        deliverRouted: (server) => server.enqueue(record),
      });
    },
  };
}

