// One hop-status sentence per hop, in hop order, for each stage's trace
// shape: 4 hops in Stage 1 (emit, route, serve, render), 5 in Stage 2 (LB
// round-robin pick), 6 in Stage 3 (cache check, then response emit), 7 in
// Stage 4 (the database hop after the cache check). The Stage 5 tail (and
// the Stage 6 host-less path, which reuses it byte-for-byte) is built by
// stage5Sentences with its own denominator.
function stage5Sentences(denom, t, from, serverAddress, snapshot) {
  const target = t.targetServer ?? '10.11';
  const worker = snapshot.workerQueue?.workerAddress ?? '10.41';
  if (t.asyncJob) {
    return [
      `Hop 1/${denom}: Browser (${from}) emits "${t.request}"`,
      `Hop 2/${denom}: Network (10.x) routes to LoadBalancer (${serverAddress})`,
      `Hop 3/${denom}: LoadBalancer (${serverAddress}) -> ${target} queue`,
      `Hop 4/${denom}: WebServer (${target}) enqueues job to WorkerQueue (10.40)`,
      `Hop 5/${denom}: WebServer (${target}) -> "202 Accepted"`,
      `Hop 6/${denom}: Network delivers 202 response to ${from}`,
      `Hop 7/${denom}: Browser (${from}) received and displayed 202 Accepted`,
      `Hop 8/${denom}: Worker (${worker}) processed job and committed to Database (10.30)`,
    ];
  }
  // Requests served synchronously keep the Stage 4 cache/database story;
  // the worker does not see them, so the tail hop reads idle.
  const db = snapshot.database ?? {};
  const primary = db.primaryAddress ?? '10.30';
  const replica = db.replicaAddress ?? '10.31';
  const lag = db.replicationLagTicks ?? 3;
  const dbOp =
    t.dbOp === 'WRITE'
      ? `Database WRITE @ Primary (${primary}) — replica lags ${lag}t`
      : t.dbOp === 'SELECT' && t.dbStale
        ? `Database SELECT @ Replica (${replica}) — STALE (lag ${lag}t)`
        : t.dbOp === 'SELECT'
          ? `Database SELECT @ Replica (${replica}) — fresh`
          : `Database SKIP — warm cache HIT (${snapshot.cache?.address ?? '10.20'})`;
  return [
    `Hop 1/${denom}: Browser (${from}) emits "${t.request}"`,
    `Hop 2/${denom}: Network (10.x) routes to LoadBalancer (${serverAddress})`,
    `Hop 3/${denom}: LoadBalancer (${serverAddress}) -> ${target} queue`,
    `Hop 4/${denom}: ${dbOp}`,
    `Hop 5/${denom}: WebServer (${target}) -> "${t.response}" (cache ${t.cacheStatus})`,
    `Hop 6/${denom}: Network delivers ${t.status} response to ${from}`,
    `Hop 7/${denom}: Browser (${from}) received and displayed ${t.status}`,
    `Hop 8/${denom}: Worker (${worker}) idle — no async jobs in this trace`,
  ];
}

// Stage 6: a hosted path (browser URL carries `<host>/<path>`) adds exactly
// two DNS hops — ask, then answer — before the Stage 5 chain; a host-less
// path reuses the Stage 5 sentences verbatim; an NX answer ends the trace
// at hop 3 with the browser rendering the NX card and no GET emitted.
function stage6Sentences(t, from, serverAddress, snapshot) {
  const dnsAddr = snapshot.dns?.address ?? '10.60';
  const denom = t.totalHops ?? 8;
  if (!t.hosted) return stage5Sentences(denom, t, from, serverAddress, snapshot);
  if (t.status === 'NX') {
    return [
      `Hop 1/${denom}: Browser (${from}) emits "${t.request}"`,
      `Hop 2/${denom}: Browser (${from}) asks DNS (${dnsAddr}) for ${t.host}`,
      `Hop 3/${denom}: DNS (${dnsAddr}) -> ${from}: NX no record for ${t.host}`,
    ];
  }
  return [
    `Hop 1/${denom}: Browser (${from}) emits "${t.request}"`,
    `Hop 2/${denom}: Browser (${from}) asks DNS (${dnsAddr}) for ${t.host}`,
    `Hop 3/${denom}: DNS (${dnsAddr}) -> ${from}: ${t.host} is ${t.dnsTarget}`,
    ...stage5Sentences(denom, t, from, serverAddress, snapshot).slice(1),
  ];
}

function hopSentences(stage, snapshot, from, serverAddress) {
  const t = snapshot.trace ?? {};
  if (stage === 5) {
    return stage5Sentences(8, t, from, serverAddress, snapshot);
  }
  if (stage === 6) {
    return stage6Sentences(t, from, serverAddress, snapshot);
  }

