import { describe, it, expect } from 'vitest';
import { createDns } from '../../js/sim/dns.js';
import { createEngine } from '../../js/sim/engine.js';

describe('createDns', () => {
  // Negative-case pin (brief §Negative-case, DNS TTL branch): a hit inside
  // ttlTicks increments cachedHits with NO authoritative consult — the
  // authoritativeHits counter moves only on the miss that filled the entry.
  it('a cache hit inside ttlTicks answers from the ledger without an authoritative consult', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });

    // Cold lookup: the ledger misses and the authoritative table answers.
    expect(dns.lookup('example.com', 1)).toEqual({
      status: 'OK',
      name: 'example.com',
      target: '10.1',
      source: 'authoritative',
      atTick: 1,
    });
    let snap = dns.snapshot(1);
    expect(snap).toMatchObject({ lookups: 1, cachedHits: 0, authoritativeHits: 1 });
    expect(snap.cache).toEqual([
      { name: 'example.com', target: '10.1', cachedAtTick: 1, expiresAtTick: 301, ttlRemaining: 300 },
    ]);

    // Warm lookup at tick 50 (well inside the 300t TTL): the ledger answers
    // and the authoritative table is not consulted again.
    expect(dns.lookup('example.com', 50)).toEqual({
      status: 'OK',
      name: 'example.com',
      target: '10.1',
      source: 'cache',
      atTick: 50,
    });
    snap = dns.snapshot(50);
    expect(snap).toMatchObject({ lookups: 2, cachedHits: 1, authoritativeHits: 1 });
    expect(snap.lastLookup).toEqual({ name: 'example.com', status: 'OK', source: 'cache', atTick: 50 });
  });

  // Negative-case pin (brief §Negative-case, DNS TTL branch): an expired
  // entry is never answered from the cache ledger — the lookup evicts it
  // and consults the authoritative table again.
  it('an expired entry is never answered from the cache ledger', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });
    dns.lookup('example.com', 1); // fills the ledger, cached at tick 1

    // At tick 301 the entry is expired: the ledger answers nothing and the
    // authoritative table re-fills it.
    expect(dns.lookup('example.com', 301)).toEqual({
      status: 'OK',
      name: 'example.com',
      target: '10.1',
      source: 'authoritative',
      atTick: 301,
    });
    const snap = dns.snapshot(301);
    expect(snap).toMatchObject({ lookups: 2, cachedHits: 0, authoritativeHits: 2 });
    expect(snap.cache).toEqual([
      {
        name: 'example.com',
        target: '10.1',
        cachedAtTick: 301,
        expiresAtTick: 601,
        ttlRemaining: 300,
      },
    ]);
  });

  // Negative-case pin (brief §1): an unknown name answers { status: 'NX' }
  // and never throws at the DNS layer; no ledger row is created.
  it('unknown names answer NX, never throw, and leave no ledger row', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });
    const answer = dns.lookup('nope.example', 7);
    expect(answer).toEqual({ status: 'NX', name: 'nope.example', atTick: 7 });
    const snap = dns.snapshot(7);
    expect(snap).toMatchObject({ lookups: 1, cachedHits: 0, authoritativeHits: 0 });
    expect(snap.cache).toEqual([]);
    expect(snap.authoritative).toEqual({ 'example.com': '10.1' });
  });

  // CHECKS: the constructor rejects a non-mini-IP address and a
  // non-positive or non-integer ttlTicks (fail-loud over silent misconfig).
  it('rejects a non mini-IP address and a non-positive ttlTicks', () => {
    expect(() => createDns({ address: '1060' })).toThrow(/invalid mini-IP/);
    expect(() => createDns({ ttlTicks: 0 })).toThrow(/ttlTicks/);
    expect(() => createDns({ ttlTicks: 2.5 })).toThrow(/ttlTicks/);
  });
});

describe('stage 6 engine wiring', () => {
  it('stage 6 engine instantiates DNS 10.60 + Router and drives hosted, NX, and host-less traces', () => {
    const engine = createEngine({ stage: 6 });
    let snap = engine.snapshot();
    expect(snap.dns.address).toBe('10.60');
    expect(snap.router).toEqual({
      leftAddress: '10.65',
      rightAddress: '20.1',
      routed: 0,
      received: [],
    });

    // Hosted trace: exactly 10 hops — emit, DNS ask, DNS answer, then the
    // Stage 5 chain — with the ledger filled from the authoritative table.
    for (let hop = 0; hop < 10; hop++) engine.traceHop({ method: 'GET', path: 'example.com/about' });
    snap = engine.snapshot();
    expect(snap.trace.hop).toBe(10);
    expect(snap.trace.totalHops).toBe(10);
    expect(snap.trace.dnsTarget).toBe('10.1');
    expect(snap.dns).toMatchObject({ lookups: 1, cachedHits: 0, authoritativeHits: 1 });
    expect(snap.browserDisplay.body).toBe('This is the about page');

    // Second hosted trace: the ledger answers (cachedHits +1) and the
    // authoritative table is NOT consulted again.
    for (let hop = 0; hop < 10; hop++) engine.traceHop({ method: 'GET', path: 'example.com/about' });
    snap = engine.snapshot();
    expect(snap.dns).toMatchObject({ lookups: 2, cachedHits: 1, authoritativeHits: 1 });

    // NX trace: 3 hops total, the browser renders the NX card, and no GET
    // is emitted (the served total does not move).
    const servedBefore = engine.snapshot().served;
    for (let hop = 0; hop < 3; hop++) engine.traceHop({ method: 'GET', path: 'nope.example/about' });
    snap = engine.snapshot();
    expect(snap.trace.hop).toBe(3);
    expect(snap.trace.totalHops).toBe(3);
    expect(snap.trace.status).toBe('NX');
    expect(snap.browserDisplay).toMatchObject({ status: 'NX', body: 'no record' });
    expect(snap.dns).toMatchObject({ lookups: 3, cachedHits: 1, authoritativeHits: 1 });
    expect(snap.served).toBe(servedBefore);

    // Host-less trace: the Stage 5 story verbatim — 8 hops, no DNS lookup
    // at all (the named counter-example: GET /about keeps the Stage 5 hop
    // count and never touches DNS).
    for (let hop = 0; hop < 8; hop++) engine.traceHop({ method: 'GET', path: '/about' });
    snap = engine.snapshot();
    expect(snap.trace.hop).toBe(8);
    expect(snap.trace.totalHops).toBe(8);
    expect(snap.trace.hosted).toBe(false);
    expect(snap.dns).toMatchObject({ lookups: 3, cachedHits: 1 });
    expect(snap.browserDisplay.body).toBe('This is the about page');

    // Stages 1-5 expose no DNS or Router at all.
    for (const stage of [1, 2, 3, 4, 5]) {
      const plain = createEngine({ stage }).snapshot();
      expect(plain.dns).toBe(null);
      expect(plain.router).toBe(null);
    }
  });

  it('rejects a stage outside 1-6', () => {
    expect(() => createEngine({ stage: 0 })).toThrow(/stage must be 1, 2, 3, 4, 5, or 6/);
    expect(() => createEngine({ stage: 7 })).toThrow(/stage must be 1, 2, 3, 4, 5, or 6/);
  });
});

import { describe, it, expect } from 'vitest';
import { createRouter } from '../../js/sim/router.js';
import { createNetwork } from '../../js/sim/network.js';
import { createWebServer } from '../../js/sim/webserver.js';

// A two-network rig mirroring the engine's Stage 6 wiring: left network is
// subnet 10.x with the router's 10.65 leg, right network is subnet 20.x
// with the router's 20.1 leg, and each side's gateway hops frames for the
// other subnet into its peer.
function buildRig() {
  const left = createNetwork({ subnet: '10' });
  const right = createNetwork({ subnet: '20' });
  const router = createRouter();
  left.registerServer('10.65', router);
  right.registerServer('20.1', router);
  left.registerServer('10.1', createWebServer({ address: '10.1' }));
  left.setGateway({ router, remoteAddress: router.rightAddress, peer: right });
  right.setGateway({ router, remoteAddress: router.leftAddress, peer: left });
  return { left, right, router };
}

describe('createRouter', () => {
  it('rejects non mini-IP legs and same-subnet legs', () => {
    expect(() => createRouter({ leftAddress: '1065' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ rightAddress: 'x.y' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ leftAddress: '10.65', rightAddress: '10.9' })).toThrow(
      /both legs sit in subnet 10\.x/,
    );
  });
});

describe('cross-subnet routing', () => {
  it('same-subnet sends keep the send and deliverToQueue contract unchanged', () => {
    const { left, router } = buildRig();
    // The wire answers exactly as it did before Stage 6.
    expect(left.send({ from: '10.2', to: '10.1', request: 'GET /about' })).toEqual({
      from: '10.2',
      to: '10.1',
      request: 'GET /about',
      response: '200 This is the about page',
    });
    left.deliverToQueue({
      id: '1:1',
      from: '10.2',
      to: '10.1',
      request: 'GET /',
      atTick: 1,
      isYou: true,
    });
    // No router hop ever happened for same-subnet traffic.
    expect(router.snapshot().routed).toBe(0);
    expect(router.snapshot().received).toEqual([]);
    // An unknown same-subnet host still fails loud with the same shape.
    expect(() => left.send({ from: '10.2', to: '10.99', request: 'GET /' })).toThrow(
      /no server at 10\.99/,
    );
  });

  it('a cross-subnet frame takes exactly one router hop and isYou rides through', () => {
    const { left, router } = buildRig();
    // The only reachable target in subnet 20 in 6a is the router's own
    // 20.1 interface; it answers with its slim diagnostic.
    expect(left.send({ from: '10.2', to: '20.1', request: 'GET /' })).toEqual({
      from: '10.2',
      to: '20.1',
      request: 'GET /',
      response: '200 Router 10.65 ⇄ 20.1',
    });
    expect(router.snapshot().routed).toBe(1);

    // deliverToQueue rides through: the record (isYou included) lands on
    // the router's 20-side, one hop counted.
    left.deliverToQueue({
      id: '2:1',
      from: '10.2',
      to: '20.1',
      request: 'GET /about',
      atTick: 2,
      isYou: true,
    });
    const snap = router.snapshot();
    expect(snap.routed).toBe(2);
    expect(snap.received).toEqual([
      { id: '2:1', from: '10.2', to: '20.1', request: 'GET /about', atTick: 2, isYou: true },
    ]);
    expect(router.lastReceived().isYou).toBe(true);
  });

  // Negative-case pin (brief §Negative-case, cross-subnet fail-loud): a
  // send into subnet 20 to an unregistered host (20.9) throws — DL-1
  // fail-loud, mirrored from the network's own unknown-host throw.
  it('a send to unregistered 20.9 fails loud after the one router hop', () => {
    const { left, router } = buildRig();
    expect(() => left.send({ from: '10.2', to: '20.9', request: 'GET /' })).toThrow(
      /no server at 20\.9/,
    );
    expect(() =>
      left.deliverToQueue({ id: '3:1', from: '10.2', to: '20.9', request: 'GET /', atTick: 3 }),
    ).toThrow(/no server at 20\.9/);
    // The hop was still taken — the router forwarded before the far side
    // rejected the frame.
    expect(router.snapshot().routed).toBe(2);
  });

  it('a subnet-scoped network rejects foreign-subnet registrations and senders', () => {
    const left = createNetwork({ subnet: '10' });
    expect(() => left.registerServer('20.5', createWebServer())).toThrow(/outside subnet 10\.x/);
    expect(() => left.send({ from: '20.2', to: '10.1', request: 'GET /' })).toThrow(
      /outside subnet 10\.x/,
    );
    // Without a subnet (Stages 1-5) nothing changes.
    const plain = createNetwork();
    plain.registerServer('20.5', createWebServer({ address: '20.5' }));
    expect(plain.send({ from: '10.2', to: '20.5', request: 'GET /' }).response).toBe(
      '200 Welcome to the home page',
    );
  });
});

import { describe, it, expect } from 'vitest';
import { describeSnapshot } from '../../js/panel/model.js';
import { componentTitle, formatComponentState } from '../../js/panel/inspector-state.js';

// Stage-boundary extraction from model.test.js (guard-file-size): the
// Stage 6 DNS/Router narrative branches are pinned here so model.test.js
// stays inside the 450-line test cap. The three negative-case contracts of
// the brief live in these pins.
const baseSnapshot = (trace) => ({
  stage: 6,
  tick: 3,
  users: 5,
  serverAddress: '10.1',
  queueDepth: 0,
  served: 1,
  avgLatencyTicks: 1,
  loadBalancer: {
    address: '10.1',
    nextBackend: '10.12',
    forwarded: 1,
    lastTarget: '10.11',
    perBackend: { '10.11': 1, '10.12': 0 },
  },
  cache: { address: '10.20', ttlTicks: 10, hits: 1, misses: 0, entries: [] },
  database: { primaryAddress: '10.30', replicaAddress: '10.31', replicationLagTicks: 3, rows: [] },
  workerQueue: { workerAddress: '10.41', pendingJobs: [] },
  dns: {
    address: '10.60',
    ttlTicks: 300,
    lookups: 1,
    cachedHits: 0,
    authoritativeHits: 1,
    cache: [{ name: 'example.com', target: '10.1', ttlRemaining: 298 }],
  },
  router: { leftAddress: '10.65', rightAddress: '20.1', routed: 0, received: [] },
  trace,
});

describe('describeSnapshot stage 6', () => {
  // Negative-case pin (brief §Negative-case, trace branch): a host-less
  // `GET /about` on stage 6 keeps the stage-5 hop count and hop texts
  // byte-identical — no DNS hop, no cross-subnet hop.
  it('stage 6 host-less GET /about keeps the stage-5 hop story byte-identical', () => {
    const snap = baseSnapshot({
      hop: 4,
      method: 'GET',
      path: '/about',
      request: 'GET /about',
      from: '10.2',
      targetServer: '10.11',
      dbOp: 'SELECT',
      dbStale: false,
      cacheStatus: 'HIT',
      response: '200 This is the about page',
      status: 200,
      totalHops: 8,
    });
    const labels = describeSnapshot(snap);
    expect(labels.stage).toBe(6);
    expect(labels.totalHops).toBe(8);
    expect(labels.hopStatus).toBe('Hop 4/8: Database SKIP — warm cache HIT (10.20)');

    const hopLabels = (hop, over = {}) =>
      describeSnapshot({ ...snap, trace: { ...snap.trace, hop, ...over } }).hopStatus;
    // The eight sentences must match the Stage 5 strings exactly.
    expect(hopLabels(1)).toBe('Hop 1/8: Browser (10.2) emits "GET /about"');
    expect(hopLabels(2)).toBe('Hop 2/8: Network (10.x) routes to LoadBalancer (10.1)');
    expect(hopLabels(3)).toBe('Hop 3/8: LoadBalancer (10.1) -> 10.11 queue');
    expect(hopLabels(4)).toBe('Hop 4/8: Database SKIP — warm cache HIT (10.20)');
    expect(hopLabels(5)).toBe('Hop 5/8: WebServer (10.11) -> "200 This is the about page" (cache HIT)');
    expect(hopLabels(6)).toBe('Hop 6/8: Network delivers 200 response to 10.2');
    expect(hopLabels(7)).toBe('Hop 7/8: Browser (10.2) received and displayed 200');
    expect(hopLabels(8)).toBe('Hop 8/8: Worker (10.41) idle — no async jobs in this trace');
  });

  // Negative-case pin (brief §3): a hosted trace adds exactly 2 DNS hops —
  // the ask and the answer — before the Stage 5 chain, at /10 denominators.
  it('a hosted stage-6 trace adds exactly 2 DNS hops to the stage-5 story', () => {
    const snap = baseSnapshot({
      hop: 3,
      method: 'GET',
      path: 'example.com/about',
      request: 'GET example.com/about',
      from: '10.2',
      host: 'example.com',
      hosted: true,
      dnsTarget: '10.1',
      targetServer: null,
      response: null,
      status: null,
      totalHops: 10,
    });
    const labels = describeSnapshot(snap);
    expect(labels.totalHops).toBe(10);
    expect(labels.hopStatus).toBe('Hop 3/10: DNS (10.60) -> 10.2: example.com is 10.1');

    const hopLabels = (hop) =>
      describeSnapshot({ ...snap, trace: { ...snap.trace, hop } }).hopStatus;
    expect(hopLabels(1)).toBe('Hop 1/10: Browser (10.2) emits "GET example.com/about"');
    expect(hopLabels(2)).toBe('Hop 2/10: Browser (10.2) asks DNS (10.60) for example.com');
    // Hops 4-10 are the Stage 5 chain verbatim, two hops later.
    expect(hopLabels(4)).toBe('Hop 4/10: Network (10.x) routes to LoadBalancer (10.1)');
    expect(hopLabels(5)).toBe('Hop 5/10: LoadBalancer (10.1) -> 10.11 queue');
    expect(hopLabels(9)).toBe('Hop 9/10: Browser (10.2) received and displayed 200');
    expect(hopLabels(10)).toBe('Hop 10/10: Worker (10.41) idle — no async jobs in this trace');
  });

  // Negative-case pin (brief §Negative-case, unknown-name branch): the NX
  // path is DNS ask + NX answer only — the trace ends at hop 3, the browser
  // renders the NX card, and no GET sentence exists to run.
  it('an unknown-host NX trace answers DNS ask + NX and never emits a GET', () => {
    const snap = baseSnapshot({
      hop: 3,
      method: 'GET',
      path: 'nope.example/about',
      request: 'GET nope.example/about',
      from: '10.2',
      host: 'nope.example',
      hosted: true,
      dnsTarget: null,
      targetServer: null,
      response: 'NX no record',
      status: 'NX',
      body: 'no record',
      totalHops: 3,
    });
    const labels = describeSnapshot(snap);
    expect(labels.totalHops).toBe(3);
    expect(labels.hopStatus).toBe('Hop 3/10: DNS (10.60) -> 10.2: NX no record for nope.example');

    const all = JSON.stringify(labels);
    expect(all).toContain('NX no record for nope.example');
    // The Stage 5 chain sentences are absent from the NX trace's story.
    expect(all).not.toContain('LoadBalancer (10.1) -> 10.11 queue');
    expect(all).not.toContain('renders a GET');
    expect(labels.browserStatus).toBe('NX (GET nope.example/about)');
    expect(labels.browserBody).toBe('no record');
  });

  it('maps the DNS and Router live state to the inspector as JSON', () => {
    const snap = baseSnapshot({
      hop: 0,
      request: 'GET /about',
      status: null,
      response: null,
    });
    const dnsState = JSON.parse(formatComponentState(snap, 'dns'));
    expect(dnsState).toEqual({
      address: '10.60',
      ttlTicks: 300,
      lookups: 1,
      cachedHits: 0,
      authoritativeHits: 1,
      lastLookup: null,
      authoritative: { 'example.com': '10.1' },
      cache: [{ name: 'example.com', target: '10.1', ttlRemaining: 298 }],
    });
    expect(componentTitle(snap, 'dns')).toBe('DNS — mini-IP 10.60');
    const routerState = JSON.parse(formatComponentState(snap, 'router'));
    expect(routerState).toEqual({
      leftAddress: '10.65',
      rightAddress: '20.1',
      routed: 0,
      received: [],
    });
    expect(componentTitle(snap, 'router')).toBe('Router — 10.65 ⇄ 20.1');
  });
});

