// DOCUMENTS: per-hop highlight targets — which node card executes the hop
// and which wire lane carries it, per stage's trace shape. Split from
// render-stage.js by responsibility (guard-file-size): the renderer reads
// the resolved { cardId, laneId }; this module owns the per-stage owner and
// lane tables. Zero engine knowledge: the snapshot's trace record in,
// highlight target out.
export function activeHopTarget(snapshot) {
  const hop = snapshot.trace?.hop ?? 0;
  if (snapshot.stage === 6) {
    const t = snapshot.trace ?? {};
    const backendCard = t.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
    const dbLane = t.dbOp === 'WRITE' ? 'packet-req-db' : 'packet-res-db';
    // Host-less paths keep the Stage 5 highlight story verbatim.
    if (!t.hosted) {
      const owners = {
        1: 'node-browser',
        2: 'node-network',
        3: 'node-lb',
        4: t.asyncJob ? 'node-queue' : 'node-db',
        5: backendCard,
        6: 'node-network',
        7: 'node-browser',
        8: 'node-worker',
      };
      const lanes = {
        1: 'packet-req-left',
        2: 'packet-req-right',
        3: 'packet-req-lb',
        4: t.asyncJob ? 'packet-req-queue' : dbLane,
        5: 'packet-res-cache',
        6: 'packet-res-right',
        7: 'packet-res-left',
        8: t.asyncJob ? 'packet-res-db' : 'packet-res-worker',
      };
      return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
    }
    // NX: the trace ends at the DNS answer — the browser renders the NX
    // card, and no Stage 5 card lights up.
    if (t.status === 'NX') {
      const owners = { 1: 'node-browser', 2: 'node-dns', 3: 'node-dns' };
      const lanes = { 1: 'packet-req-left', 2: 'packet-req-dns', 3: 'packet-res-dns' };
      return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
    }
    // Hosted paths shift the Stage 5 story two hops later (the two DNS hops
    // ask + answer in between).
    const owners = {
      1: 'node-browser',
      2: 'node-dns',
      3: 'node-dns',
      4: 'node-network',
      5: 'node-lb',
      6: t.asyncJob ? 'node-queue' : 'node-db',
      7: backendCard,
      8: 'node-network',
      9: 'node-browser',
      10: 'node-worker',
    };
    const lanes = {
      1: 'packet-req-left',
      2: 'packet-req-dns',
      3: 'packet-res-dns',
      4: 'packet-req-right',
      5: 'packet-req-lb',
      6: t.asyncJob ? 'packet-req-queue' : dbLane,
      7: 'packet-res-cache',
      8: 'packet-res-right',
      9: 'packet-res-left',
      10: t.asyncJob ? 'packet-res-db' : 'packet-res-worker',
    };
    return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
  }
  if (snapshot.stage === 5) {
    // Async POST /jobs walks browser -> lb -> enqueue -> 202 -> worker
    // commit; every other request keeps the Stage 4 cache/db story and the
    // worker reads idle on the tail hop.
    const backendCard =
      snapshot.trace?.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
    const dbLane = snapshot.trace?.dbOp === 'WRITE' ? 'packet-req-db' : 'packet-res-db';
    const owners = snapshot.trace?.asyncJob
      ? {
          1: 'node-browser',
          2: 'node-network',
          3: 'node-lb',
          4: 'node-queue',
          5: 'node-webserver',
          6: 'node-network',
          7: 'node-browser',
          8: 'node-worker',
        }
      : {
          1: 'node-browser',
          2: 'node-network',
          3: 'node-lb',
          4: 'node-db',
          5: backendCard,
          6: 'node-network',
          7: 'node-browser',
          8: 'node-worker',
        };
    const lanes = snapshot.trace?.asyncJob
      ? {
          1: 'packet-req-left',
          2: 'packet-req-right',
          3: 'packet-req-lb',
          4: 'packet-req-queue',
          5: 'packet-res-cache',
          6: 'packet-res-right',
          7: 'packet-res-left',
          8: 'packet-res-db',
        }
      : {
          1: 'packet-req-left',
          2: 'packet-req-right',
          3: 'packet-req-lb',
          4: dbLane,
          5: 'packet-res-cache',
          6: 'packet-res-right',
          7: 'packet-res-left',
          8: 'packet-res-worker',
        };
    return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
  }
  if (snapshot.stage === 4) {
    const backendCard =
      snapshot.trace?.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
    const dbLane = snapshot.trace?.dbOp === 'WRITE' ? 'packet-req-db' : 'packet-res-db';
    const owners = {
      1: 'node-browser',
      2: 'node-network',
      3: 'node-lb',
      4: 'node-cache',
      5: 'node-db',
      6: backendCard,
      7: 'node-browser',
    };
    const lanes = {
      1: 'packet-req-left',
      2: 'packet-req-right',
      3: 'packet-req-lb',
      4: 'packet-req-cache',
      5: dbLane,
      6: 'packet-res-cache',
      7: 'packet-res-left',
    };
    return { cardId: owners[hop], laneId: lanes[hop] };
  }
  if (snapshot.stage === 3) {
    const backendCard =
      snapshot.trace?.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
    const owners = {
      1: 'node-browser',
      2: 'node-network',
      3: 'node-lb',
      4: 'node-cache',
      5: backendCard,
      6: 'node-browser',
    };
    const lanes = {
      1: 'packet-req-left',
      2: 'packet-req-right',
      3: 'packet-req-lb',
      4: 'packet-req-cache',
      5: 'packet-res-cache',
      6: 'packet-res-left',
    };
    return { cardId: owners[hop], laneId: lanes[hop] };
  }
  if (snapshot.stage === 2) {
    const backendCard =
      snapshot.trace?.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
    const owners = {
      1: 'node-browser',
      2: 'node-network',
      3: 'node-lb',
      4: backendCard,
      5: 'node-browser',
    };
    const lanes = {
      1: 'packet-req-left',
      2: 'packet-req-right',
      3: 'packet-req-lb',
      4: 'packet-res-lb',
      5: 'packet-res-left',
    };
    return { cardId: owners[hop], laneId: lanes[hop] };
  }
  const owners = { 1: 'node-browser', 2: 'node-network', 3: 'node-webserver', 4: 'node-browser' };
  const lanes = {
    1: 'packet-req-left',
    2: 'packet-req-right',
    3: 'packet-res-right',
    4: 'packet-res-left',
  };
  return { cardId: owners[hop], laneId: lanes[hop] };
}

// DOCUMENTS: stage-shape DOM writes, split from render.js by
// responsibility (guard-file-size): which cards and wire lanes are visible
// per stage, which card and wire lane carries the active hop (the per-hop
// target tables live in hop-targets.js), the crowd dots, and the compact
// browser nodes on the outer client ring. Zero engine knowledge: snapshots
// and layout geometry in, DOM writes out.
import { activeHopTarget } from './hop-targets.js';

const $ = (id) => document.getElementById(id);

// The lane ids highlighted during a trace; looked up lazily because the
// Stage 6 lanes are built by stage6-nodes.js after module load.
const LANES = [
  'packet-req-left',
  'packet-res-left',
  'packet-req-right',
  'packet-res-right',
  'packet-req-lb',
  'packet-res-lb',
  'packet-req-cache',
  'packet-res-cache',
  'packet-req-db',
  'packet-res-db',
  'packet-req-queue',
  'packet-res-queue',
  'packet-req-worker',
  'packet-res-worker',
  'packet-req-dns',
  'packet-res-dns',
];

// Stage-switch hook: viewport.js registers a callback so camera + world
// layout resync the moment the topology toggles.
let stageRenderedHook = null;

export function onStageRendered(fn) {
  stageRenderedHook = fn;
}

export function renderStageTopology(stage) {
  const hasLb = stage >= 2;
  const hasCache = stage >= 3;
  const hasDb = stage >= 4;
  const hasWorkers = stage === 5;
  const hasDns = stage >= 6;
  $('node-lb').hidden = !hasLb;
  $('wire-lb-backends').hidden = !hasLb;
  $('node-webserver-2').hidden = !hasLb;
  $('node-cache').hidden = !hasCache;
  $('wire-servers-cache').hidden = !hasCache;
  $('node-db').hidden = !hasDb;
  $('wire-cache-db').hidden = !hasDb;
  $('node-queue').hidden = !hasWorkers;
  $('wire-cache-queue').hidden = !hasWorkers;
  $('node-worker').hidden = !hasWorkers;
  $('wire-queue-worker').hidden = !hasWorkers;
  // Stage 6 cards live in stage6-nodes.js (panel.html sits at its line
  // cap); their wire lane toggles with the DNS card.
  const dnsCard = document.getElementById('node-dns');
  const dnsLane = document.getElementById('wire-dns');
  const routerCard = document.getElementById('node-router');
  if (dnsCard) dnsCard.hidden = !hasDns;
  if (dnsLane) dnsLane.hidden = !hasDns;
  if (routerCard) routerCard.hidden = !hasDns;
  $('network-role-10-1').textContent = hasLb ? 'LoadBalancer -> 10.11, 10.12' : 'WebServer';
  for (const pill of document.querySelectorAll('.stage-pill[data-stage]')) {
    const active = Number(pill.dataset.stage) === stage;
    pill.classList.toggle('active-stage', active);
    if (active) pill.setAttribute('aria-current', 'true');
    else pill.removeAttribute('aria-current');
  }
  if (stageRenderedHook) stageRenderedHook(stage);
}

export function renderHopHighlights(snapshot, selectedComponent) {
  const { cardId, laneId } = activeHopTarget(snapshot);
  for (const card of document.querySelectorAll('.node-card')) {
    card.classList.toggle('active-hop', card.id === cardId);
    card.classList.toggle('selected-node', card.dataset.component === selectedComponent);
  }
  for (const id of LANES) {
    const node = document.getElementById(id);
    if (node) node.classList.toggle('lane-active', id === laneId);
  }
}

export function renderDots(n) {
  $('user-dots').replaceChildren(
    ...Array.from({ length: n }, () => {
      const dot = document.createElement('span');
      dot.className = 'user-dot';
      return dot;
    }),
  );
}

// CHECKS: compact outer-ring browser nodes rebuild from the layout's
// browser slots so a re-spaced or re-populated ring leaves no stale or
// ghost buttons behind.
export function renderRingBrowsers(slots, activeAddress) {
  const ring = $('browser-ring-nodes');
  if (!ring) return;
  ring.replaceChildren(
    ...slots
      .filter((slot) => slot.address !== activeAddress)
      .map((slot) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'browser-compact';
        button.dataset.testid = `browser-node-${slot.address}`;
        button.dataset.address = slot.address;
        button.style.left = `${slot.x}px`;
        button.style.top = `${slot.y}px`;
        const chip = document.createElement('span');
        chip.className = 'ip-chip';
        chip.textContent = slot.address;
        const status = document.createElement('span');
        status.className = 'browser-compact-status';
        status.textContent = slot.lastDisplay ? String(slot.lastDisplay.status) : 'idle';
        button.replaceChildren(chip, status);
        return button;
      }),
  );
}

